package org.marketreview.nativeapp;
import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
final class MigrationStatusChecks {
 interface Work{void run()throws Exception;}
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static void refuses(Work work)throws Exception{boolean failed=false;try{work.run();}catch(Exception e){failed=true;}check(failed,"expected refusal");}
 static JSONObject fixture()throws Exception{JSONArray a=new JSONArray();for(int i=0;i<55;i++)a.put(new JSONObject().put("id","item"+i).put("title","审查项"+i).put("route","docs").put("platform",i%2==0?"Windows":"Android").put("module","研究").put("nativeStatus",i==0?"待迁移":"部分实现").put("scope","长缺口 ".repeat(500)+"尾段"+i).put("evidence","opaque:"+i).put("verificationDimensions",new JSONObject().put("code","存在").put("fixture","通过")));return new JSONObject().put("schema","native-migration-status/v1").put("version","fixture").put("asOf","2000-01-01").put("entries",a).put("scopeNote","审查项不是独立首页");}
 static void model()throws Exception{JSONObject s=fixture();String before=MigrationStatusModel.json(s);check(MigrationStatusModel.filter(s,new JSONObject().put("search","尾段54")).length()==1,"full gap search");check(MigrationStatusModel.filter(s,new JSONObject().put("platform","Android")).length()==27,"platform filter");check(MigrationStatusModel.filter(s,new JSONObject().put("acceptance","未知")).length()==55,"missing acceptance remains unknown");check(MigrationStatusModel.detail(s.getJSONArray("entries").getJSONObject(54)).contains("尾段54")&&MigrationStatusModel.summary(s).contains("0完整验收"),"fixture/code not acceptance");JSONObject bad=new JSONObject(before);bad.getJSONArray("entries").put(bad.getJSONArray("entries").get(0));refuses(()->MigrationStatusModel.validate(bad));check(MigrationStatusModel.json(s).equals(before),"readonly snapshot unchanged");}
 public static void main(String[] args)throws Exception{model();if(args.length>0){JSONObject actual=MigrationStatusModel.validate(new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8)));check(actual.getJSONArray("entries").length()==117,"117 audits complete");System.out.println(MigrationStatusModel.summary(actual));}System.out.println("PASS MigrationStatus production Java full filters/search/full gap/unknown acceptance/readonly original; model only");}
 static void run(FlowInstrumentation f)throws Exception{model();JSONObject snapshot=fixture();MigrationStatusScreen[] saved=new MigrationStatusScreen[1];int[] jumps={0};f.ui(()->{try{MigrationStatusScreen screen=new MigrationStatusScreen(f.activity,()->snapshot,(id,route)->!id.equals("item0"),(id,route)->jumps[0]++,(id,ref)->new JSONObject().put("text","完整证据原文".repeat(250000)).put("source","fixture").put("available",true));screen.restoreState(new JSONObject().put("filters",new JSONObject()).put("page",2));check(screen.page==2&&screen.rows.getChildCount()==15,"full pagination restoration");JSONObject state=screen.saveState().put("view",1).put("entry",snapshot.getJSONArray("entries").getJSONObject(0)).put("entryVersion","fixture").put("entryAsOf","2000-01-01");screen.restoreState(state);check(!screen.jump.isEnabled()&&screen.back()&&!screen.back(),"unmounted entry disabled/internal back");state.put("entry",snapshot.getJSONArray("entries").getJSONObject(1));screen.restoreState(state);screen.readEvidence.performClick();check(screen.proof.getText().toString().contains("完整证据原文".repeat(250000)),"long proof complete");MigrationStatusScreen recreated=new MigrationStatusScreen(f.activity,()->snapshot,(id,route)->true,(id,route)->jumps[0]++,null);recreated.restoreState(screen.saveState());check(recreated.view==2&&recreated.page==2&&recreated.proof.getText().toString().contains("完整证据原文".repeat(250000)),"reader recreation");recreated.setDarkTheme(true);check(recreated.back(),"proof internal back");snapshot.getJSONArray("entries").getJSONObject(1).put("route","wrong");recreated.jump.performClick();check(jumps[0]==0,"stale route refused");saved[0]=recreated;}catch(Exception e){throw new RuntimeException(e);}});f.ui(()->check(saved[0].page==2,"late spinner callbacks preserve page"));}
}
